local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"
local fishingComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
local KTool = CS.Engine.Lib.KTool

---@class FishPoolActivityFeedCellNode
---@field ImgBtnFrame                   	Game.Native.Common.UISwitchImage        
---@field TxtNum                        	UnityEngine.RectTransform               
---@field BtnQuest                      	UnityEngine.RectTransform                                            
local FishPoolActivityFeedCellNode = Class("FishPoolActivityFeedCellNode")
function FishPoolActivityFeedCellNode:__init() 
    self._data = nil
    self._parLuaScr = nil
end

function FishPoolActivityFeedCellNode:__delete()
    self._data = nil
    self._parLuaScr = nil
end

function FishPoolActivityFeedCellNode:Awake()    
end

function FishPoolActivityFeedCellNode:Start()
end

function FishPoolActivityFeedCellNode:Refresh(data, parLua)
    if not data then
        return
    end
    self._data = data
    self._parLuaScr = parLua

    self:FillSelf()
end

function FishPoolActivityFeedCellNode:FillSelf()
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = FishingUtils.GetExchangeReward(self._data.id)
        scr:FreshBaseUI(t, false)
    end

    local isDraw = FishingUtils.IsDrawExchangeReward(self._data.id)
    local isCanDraw = FishingUtils.IsUnlockExchangeReward(self._data.id)
    local isUnlock = FishingUtils.IsUnlockExchangeReward(self._data.id)

    CfUtils.SetUISwitchImage(self.ImgFrame1, (not isDraw and isUnlock and GoodsUtils.GetThingNo(self._data.cost) >= checkNumber(self._data.costNum)) and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgFrame2, (not isDraw and isUnlock and GoodsUtils.GetThingNo(self._data.cost) >= checkNumber(self._data.costNum)) and 2 or 1)

    CfUtils.SetActive(self.Complete, isDraw)
    CfUtils.SetActive(self.UnLock, not isDraw and isCanDraw)
    CfUtils.SetActive(self.Lock, not isDraw and not isCanDraw)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.cost)
    if goodsVo then
        CfUtils.FillImage(self.ImgGoods, goodsVo.photoPath)
    end
    CfUtils.FillText(self.TextNumber, self._data.costNum)
    CfUtils.FillText(self.TextDesc, string.gsub(self._data.desc, "\\n", "\n"))

    if checkNumber(self._data.type) == 2 then
        CfUtils.SetActive(self.FontStyleWithGoodIconButton.transform:Find("Unlock"), isUnlock)
        CfUtils.SetActive(self.FontStyleWithGoodIconButton.transform:Find("Lock"), not isUnlock)

        if isUnlock and GoodsUtils.GetThingNo(self._data.cost) >= checkNumber(self._data.costNum) then
            CfUtils.SetUISwitchImage(self.FontStyleWithGoodIconButton, 1)
        else
            CfUtils.SetUISwitchImage(self.FontStyleWithGoodIconButton, 2)
        end

        SetButtonAction(self.BtnReward, function()
            goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.reward)
            GameUtils.ShowCommonTipsBoard(self.BtnReward.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)

        SetButtonAction(self.FontStyleWithGoodIconButton, Bind(self, self.OnBtnExchange))
        CfUtils.FillFontStyleWithGoodIconButtonNode(self.FontStyleWithGoodIconButton, self._data.cost, "x"..self._data.costNum)
    else
        local fontStyleButton = KTool.GetComponent(self.FontStyleButton.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))

        if isUnlock and GoodsUtils.GetThingNo(self._data.cost) >= checkNumber(self._data.costNum) then
            fontStyleButton:ResetFontStyle("B12")
        else
            fontStyleButton:ResetFontStyle("B19")
        end

        SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnExchange))
    end
end

function FishPoolActivityFeedCellNode:OnBtnExchange()
    local isUnlock = FishingUtils.IsUnlockExchangeReward(self._data.id)
    if not isUnlock then
        GameUtils.Toast(localize("暂未解锁"))
        return
    end

    if GoodsUtils.GetThingNo(self._data.cost) < checkNumber(self._data.costNum) then
        GameUtils.Toast(localize("道具不足"))
        return
    end

    fishingComponent:FishingChallengeExchangeReq(self._data.id, function(rewardShow)
        local rewards = {
            {goodsId = self._data.cost, num = checkNumber(self._data.costNum) * -1}
        }
        GoodsUtils.DrawRewards(rewards, true)

        self._parLuaScr:InitData()
        self._parLuaScr:FillSelf()

        self._parLuaScr:PlaySpine("Feeding", false)
        
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        self._co = cs_coroutine.start(function()
            CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("FishPoolActivityFeedCellNode")
            coroutine.yield(WaitForSeconds(CfUtils.GetSpineTime(self._parLuaScr.Container.transform:Find("BgNode/Cat"), "Feeding")))
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardShow } })
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("FishPoolActivityFeedCellNode")
        end)

        local vo = FishingUtils.GetFishActivityPlanVo(self._parLuaScr._activityId)

        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayVoice("Audio/UI_General", "ui_fishActivity_eat_"..vo.changeId)
    end)
end

function FishPoolActivityFeedCellNode:OnDestroy()
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return FishPoolActivityFeedCellNode
